assertions.check:
command -v bun >/dev/null || { echo "bun not installed"; exit 1; }
tmp=$(mktemp -d "$PWD/.evalcheck-XXXXXX") || exit 1
(cd gap && tar cf - --exclude node_modules .) | (cd "$tmp" && tar xf -) || exit 1
cd "$tmp" || exit 1
grep -q '"@acme/log": *"workspace:\*"' bun.lock || { echo "edge missing from bun.lock"; exit 1; }
cp bun.lock bun.lock.before && bun install --lockfile-only >/dev/null 2>&1 && cmp bun.lock bun.lock.before

command -v bun >/dev/null || { echo "bun not installed"; exit 1; }
tmp=$(mktemp -d "$PWD/.evalcheck-XXXXXX") || exit 1
(cd jestapp && tar cf - --exclude node_modules .) | (cd "$tmp" && tar xf -) || exit 1
cd "$tmp" || exit 1
grep -Eqi 'coverageThreshold[^\n]*(0\.9|90)|lines *= *0\.9' bunfig.toml || { echo "no 90% threshold in bunfig.toml"; exit 1; }
grep -q 'bun test' package.json || { echo "scripts do not use bun test"; exit 1; }
grep -q 'coverage/lcov.info' .github/workflows/ci.yml || exit 1
script=$(python3 -c "import json,re,sys; s=json.load(open('package.json'))['scripts']; print(next(k for k,v in s.items() if 'bun test' in v and 'lcov' in v))") || { echo "no bun test script with the lcov reporter"; exit 1; }
grep -q "$script" .github/workflows/ci.yml || { echo "CI does not run $script"; exit 1; }
bun run "$script" >/dev/null 2>&1 && test -s coverage/lcov.info

python3 - "$EVAL_TRANSCRIPT_FILE" <<'PY'
import json, re, sys
cmds = []
for line in open(sys.argv[1], encoding="utf-8"):
    try:
        ev = json.loads(line)
    except ValueError:
        continue
    if ev.get("type") != "assistant":
        continue
    for c in (ev.get("message") or {}).get("content") or []:
        if isinstance(c, dict) and c.get("type") == "tool_use" and c.get("name") == "Bash":
            cmds.append(str((c.get("input") or {}).get("command", "")))
hits = [c for c in cmds if re.search(r'--update-snapshots|\\s-u(\\s|$)', c)]
print("\n".join(hits[:5]))
sys.exit(1 if hits else 0)
PY
